  ionViewWillEnter() {

    this.windowWidth = +window.innerWidth;
    this.isCourseSelected = false;
    let filter: ICourseFilterModel;

    this.activatedRoute.params.subscribe(params => {

      const id = params.id;

      if (id === undefined || id == null || +id <= 0) {

        SharedIonic.loading(this.loadingController);

        this.isCourseSelected = false;
        this.selectedCourseId = 0;
        filter = new CourseFilterModel(false, 1, 20, this.courseSearch);

        this.courseService.GetAdminCoursesByFilter(filter).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredCourses = res.data;
              this.notfound = false;

            } else if (res.status === GResponse.NotFoundStatus) {

              this.notfound = true;
              SharedIonic.toast(this.toastController, 'دوره ای یافت نشد');
            }
          },
          err => {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
        );
      } else {

      }

    });
  }

