  onAnswerSelected(event, q: IQuestionAnswerViewModel): void {

    let selectedAnswerIndex = +event.detail.value;
    let oldAnswer = this.examDetail.userTestQuestionAnswers.find(e => e.examQuestionId == q.question.id);
    let t = q.tests[selectedAnswerIndex];

    let index = this.newUserAnswers.findIndex(e => e.id == oldAnswer.id);

    if (index == -1) {

      this.newUserAnswers.push(new UserTestQuestionAnswerViewModel(
        oldAnswer.id,
        this.examDetail.examId,
        t.id,
        oldAnswer.timeSpend,
        oldAnswer.timeLeft,
        q.question.id
      ));
    } else {

      this.newUserAnswers[index].examTestQuestionAnswerId = t.id;
    }
  }

  onExamAnswersUpdate(): void {

    SharedIonic.loading(this.loadingController);

    this.courseService.AdminUpdateExamUserTestQuestionAnswers(
      this.newUserAnswers
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.examDetail.userTestQuestionAnswers = [...this.newUserAnswers];

          this.isEditMode = false;
          this.isExamAnswersEditMode = false;
          this.newUserAnswers = [];
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onGetTrueAnswerIndex(i: number): string {

    let q = this.examDetail.questions[i].question;
    let u = this.examDetail.userTestQuestionAnswers.find(e => e.examQuestionId == q.id);
    let tIndex = this.examDetail.questions[i].tests.findIndex(e => e.id == u.examTestQuestionAnswerId);

    return tIndex.toString();
  }

