  segmentChanged(ev: any) {

    this.isLoading = true;

    if (this.segmentSelected == 'Update') {

      SharedIonic.loading(this.loadingController);

      this.examQuestionsFilter = new ExamQuestionFilter(this.selectedCourseId);

      this.courseService.GetAdminExamQuestionByFilter(this.examQuestionsFilter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {

            this.examQuestionsFilter = res.data;
            this.isLoading = false;

          } else {
            this.segmentSelected = 'Add';
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          this.segmentSelected = 'Add';
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    } else if (this.segmentSelected == 'Exam') {

      SharedIonic.loading(this.loadingController);

      this.examsFilter = new ExamFilter(this.selectedCourseId);

      this.courseService.GetAdminExamsByFilter(this.examsFilter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {

            this.examsFilter = res.data;
            this.isExamQuestionSelected = false;
            this.isLoading = false;
          } else {
            this.segmentSelected = 'Add';
            SharedIonic.toast(this.toastController, 'آزمونی وجود ندارد');
          }
        },
        err => {
          this.segmentSelected = 'Add';
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

